export type ParsedRequestInstruction<
  TProgram extends string = typeof PAYMVC_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    from: TAccountMetas[0];
    fromProfile: TAccountMetas[1];
    payerProfile: TAccountMetas[2];
    entry: TAccountMetas[3];
    fromActivity: TAccountMetas[4];
    payerActivity: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: RequestInstructionData;
};

export function parseRequestInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRequestInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      from: getNextAccount(),
      fromProfile: getNextAccount(),
      payerProfile: getNextAccount(),
      entry: getNextAccount(),
      fromActivity: getNextAccount(),
      payerActivity: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRequestInstructionDataDecoder().decode(instruction.data),
  };
}
